function ask(){if(!message.trim())return;const text=message,lower=text.toLowerCase();setMessage('');let reply='Tell me a city (Lagos, Abuja, Ibadan or Port Harcourt), your budget, and land or house.';const location=['Lagos','Abuja','Ibadan','Port Harcourt'].find(c=>lower.includes(c.toLowerCase()));const category=lower.includes('land')?'Land':lower.includes('house')||lower.includes('bedroom')||lower.includes('duplex')?'House':null;const match=lower.match(/(?:₦|under\s*)?(\d+(?:\.\d+)?)\s*(?:million|m\b)/);const limit=match?Number(match[1])*1e6:Infinity;const bedroomMatch=lower.match(/(\d+)\s*[- ]?bedroom/);const beds=bedroomMatch?Number(bedroomMatch[1]):0;const results=listings.filter(p=>(!location||p.city===location)&&(!category||p.type===category)&&p.price<=limit&&p.beds>=beds);if(location||category||match){setMinimumBeds('Any bedrooms');setAssistantLimit(Number.isFinite(limit)?limit:null);setAssistantBeds(beds);setCity(location||'All locations');setType(category||'All properties');setBudget('Any budget');setOnlySaved(false);reply=results.length?`I found ${results.length} catalogue match${results.length===1?'':'es'}: ${results.slice(0,3).map(p=>p.title+' ('+money(p.price)+')').join('; ')}. Your property filters are updated. Close the assistant and open Explore. What is your preferred area and family size?`:'No catalogue matches yet. Try a wider location or budget.'}setChat(c=>[...c,{role:'user',text},{role:'assistant',text:reply}])}
